import { ChatCircleDotsIcon, PhoneIcon, SirenIcon } from '@phosphor-icons/react';
import { useTranslation } from 'react-i18next';
import { useCrisisResources } from './resources';

interface CrisisCardProps {
  headingId?: string;
  /** Rendered heading level; the dialog uses h2, an inline card inside a page uses h2 or h3. */
  headingLevel?: 2 | 3;
}

/**
 * Fixed, human-reviewed crisis content. It is never generated by a model and is identical
 * wherever it appears (dialog, questionnaire result, chat).
 */
export function CrisisCard({ headingId = 'crisis-title', headingLevel = 2 }: CrisisCardProps) {
  const { t } = useTranslation();
  const resources = useCrisisResources();
  const helpline = resources.find((r) => r.kind === 'helpline');
  const emergency = resources.find((r) => r.kind === 'emergency');
  const Heading = headingLevel === 2 ? 'h2' : 'h3';
  const grounding = t('crisis.groundingSteps', { returnObjects: true }) as string[];

  return (
    <div className="overflow-hidden rounded-[1.5rem] bg-surface ring-1 ring-crisis/25">
      <div className="bg-crisis-soft px-6 pt-7 pb-6 sm:px-8">
        <Heading
          id={headingId}
          className="font-display text-[clamp(1.6rem,4.5vw,2.1rem)] leading-tight font-semibold tracking-tight text-ink"
        >
          {t('crisis.title')}
        </Heading>
        <p className="mt-3 max-w-[54ch] leading-relaxed text-ink-soft">{t('crisis.body')}</p>
      </div>

      <div className="grid gap-5 px-6 py-6 sm:px-8">
        {helpline && (
          <div>
            <a
              href={`tel:${helpline.dial}`}
              className="group flex min-h-16 items-center justify-between gap-4 rounded-full bg-crisis py-2 pr-2 pl-6 text-crisis-ink transition-transform duration-500 ease-spring active:scale-[0.98]"
            >
              <span className="font-semibold">
                {t('crisis.callNow', { name: helpline.name, number: helpline.display_number })}
              </span>
              <span className="flex size-12 shrink-0 items-center justify-center rounded-full bg-crisis-ink/15 transition-transform duration-500 ease-spring group-hover:scale-105">
                <PhoneIcon size={22} weight="fill" aria-hidden />
              </span>
            </a>
            <p className="mt-3 px-2 text-sm leading-relaxed text-ink-soft">
              {helpline.description}
            </p>
            {helpline.alternate_dial && helpline.alternate_display_number && (
              <p className="mt-1 px-2 text-sm text-ink-soft">
                {t('crisis.alsoReachable')}{' '}
                <a
                  href={`tel:${helpline.alternate_dial}`}
                  className="font-semibold text-ink underline underline-offset-4 tabular-nums"
                >
                  {helpline.alternate_display_number}
                </a>
              </p>
            )}
          </div>
        )}

        {emergency && (
          <a
            href={`tel:${emergency.dial}`}
            className="flex items-start gap-4 rounded-[1.25rem] p-4 ring-1 ring-line transition-colors duration-300 ease-out-soft hover:bg-surface-sunk"
          >
            <span className="flex size-11 shrink-0 items-center justify-center rounded-full bg-crisis-soft text-crisis">
              <SirenIcon size={20} weight="fill" aria-hidden />
            </span>
            <span>
              <span className="block font-semibold text-ink">
                {t('crisis.emergency', { number: emergency.display_number })}
              </span>
              <span className="mt-0.5 block text-sm leading-relaxed text-ink-soft">
                {emergency.description}
              </span>
            </span>
          </a>
        )}

        <div className="flex items-start gap-4 rounded-[1.25rem] bg-surface-sunk p-4">
          <span className="flex size-11 shrink-0 items-center justify-center rounded-full bg-surface text-accent">
            <ChatCircleDotsIcon size={20} weight="light" aria-hidden />
          </span>
          <div>
            <p className="font-semibold text-ink">{t('crisis.trustedTitle')}</p>
            <p className="mt-1 text-sm leading-relaxed text-ink-soft">{t('crisis.trustedBody')}</p>
          </div>
        </div>

        <section aria-labelledby={`${headingId}-grounding`}>
          <h3 id={`${headingId}-grounding`} className="font-semibold text-ink">
            {t('crisis.groundingTitle')}
          </h3>
          <ol className="mt-3 grid gap-2 sm:grid-cols-2">
            {grounding.map((step, index) => (
              <li
                key={step}
                className="flex items-center gap-3 rounded-full bg-canvas px-4 py-2.5 text-sm text-ink-soft ring-1 ring-line"
              >
                <span className="font-display text-base font-semibold text-accent tabular-nums">
                  {5 - index}
                </span>
                {step}
              </li>
            ))}
          </ol>
        </section>

        <p className="text-xs leading-relaxed text-ink-muted">{t('crisis.disclaimer')}</p>
      </div>
    </div>
  );
}
